function PANEL:BindNodeInput(node)
	if not IsValid(node) or node.RGP_PanInputBound then
		return
	end
	node.RGP_PanInputBound = true

	local nodeOnMousePressed = node.OnMousePressed
	node.OnMousePressed = function(panel, mouseCode)
		if mouseCode == MOUSE_MIDDLE or (mouseCode == MOUSE_LEFT and input.IsControlDown()) then
			self:StartPanning()
			return
		end

		if nodeOnMousePressed then
			return nodeOnMousePressed(panel, mouseCode)
		end
	end

	if IsValid(node.Label) then
		local labelOnMousePressed = node.Label.OnMousePressed
		node.Label.OnMousePressed = function(label, mouseCode)
			if mouseCode == MOUSE_MIDDLE or (mouseCode == MOUSE_LEFT and input.IsControlDown()) then
				self:StartPanning()
				return
			end

			if labelOnMousePressed then
				return labelOnMousePressed(label, mouseCode)
			end
		end
	end

	local nodeOnNodeAdded = node.OnNodeAdded
	node.OnNodeAdded = function(parentNode, childNode)
		if nodeOnNodeAdded then
			nodeOnNodeAdded(parentNode, childNode)
		end

		self:BindNodeInput(childNode)
		self:InvalidateLayout()
	end

	for _, childNode in ipairs(node:GetChildNodes()) do
		self:BindNodeInput(childNode)
	end
end

function PANEL:GetContentWidth()
	local contentWidth = 0
	local textInset = self:ShowIcons() and 44 or 24

	local function measureNode(node, depth, indentSize)
		if not IsValid(node) then
			return
		end

		if not node:IsRootNode() then
			surface.SetFont(node.Label:GetFont() or "DermaDefault")
			local textWidth = surface.GetTextSize(node:GetText())
			contentWidth = math.max(contentWidth, textWidth + textInset + depth * indentSize)
		end

		if node:GetExpanded() then
			for _, childNode in ipairs(node:GetChildNodes()) do
				measureNode(childNode, depth + 1, indentSize)
			end
		end
	end

	measureNode(self.RootNode, 0, self:GetIndentSize())

	for _, child in ipairs(self.pnlCanvas:GetChildren()) do
		if child == self.RootNode or not child.Root then
			continue
		end

		local rootNode = child:Root()
		if IsValid(rootNode) then
			self:BindNodeInput(rootNode)
			local indentSize = child:GetIndentSize()
			measureNode(rootNode, 0, indentSize)
		end
	end

	return contentWidth + 4
end

