function PANEL:PerformLayoutInternal()
	self:Rebuild()

	local width = self:GetWide()
	local height = self:GetTall()
	local contentWidth = self:GetContentWidth()
	local contentHeight = self.pnlCanvas:GetTall()
	local verticalBarWidth = self.VBar:GetWide()
	local horizontalBarHeight = self.HBar:GetTall()
	local showVertical = contentHeight > height
	local showHorizontal = contentWidth > width - (showVertical and verticalBarWidth or 0)

	for _ = 1, 2 do
		local viewWidth = width - (showVertical and verticalBarWidth or 0)
		local viewHeight = height - (showHorizontal and horizontalBarHeight or 0)
		showVertical = contentHeight > viewHeight
		showHorizontal = contentWidth > width - (showVertical and verticalBarWidth or 0)
	end

	local viewWidth = width - (showVertical and verticalBarWidth or 0)
	local viewHeight = height - (showHorizontal and horizontalBarHeight or 0)
	local canvasWidth = math.max(contentWidth, viewWidth)

	self.pnlCanvas:SetWide(canvasWidth)
	self.VBar:SetUp(viewHeight, contentHeight)
	self.HBar:SetUp(viewWidth, canvasWidth)

	self.VBar:SetPos(width - verticalBarWidth, 0)
	self.VBar:SetSize(verticalBarWidth, viewHeight)
	self.HBar:SetPos(0, height - horizontalBarHeight)
	self.HBar:SetSize(viewWidth, horizontalBarHeight)
	self.pnlCanvas:SetPos(self.HBar:GetOffset(), self.VBar:GetOffset())
	self.HBar:MoveToFront()
	self.VBar:MoveToFront()
end

function PANEL:OnMouseWheeled(delta)
	if input.IsKeyDown(KEY_LSHIFT) or input.IsKeyDown(KEY_RSHIFT) then
		return self.HBar:OnMouseWheeled(delta)
	end

	return self.VBar:OnMouseWheeled(delta)
end

function PANEL:StartPanning()
	local cursorX, cursorY = self:ScreenToLocal(gui.MouseX(), gui.MouseY())
	self.PanStartX = cursorX
	self.PanStartY = cursorY
	self.PanStartScrollX = self.HBar:GetScroll()
	self.PanStartScrollY = self.VBar:GetScroll()
	self.Panning = true
	self:MouseCapture(true)
end

function PANEL:OnMousePressed(mouseCode)
	if mouseCode == MOUSE_MIDDLE then
		self:StartPanning()
	end
end

function PANEL:OnCursorMoved()
	if not self.Panning then
		return
	end

	local cursorX, cursorY = self:ScreenToLocal(gui.MouseX(), gui.MouseY())
	self.HBar:SetScroll(self.PanStartScrollX + self.PanStartX - cursorX)
	self.VBar:SetScroll(self.PanStartScrollY + self.PanStartY - cursorY)
end

function PANEL:OnMouseReleased(mouseCode)
	if (mouseCode ~= MOUSE_MIDDLE and mouseCode ~= MOUSE_LEFT) or not self.Panning then
		return
	end

	self.Panning = false
	self:MouseCapture(false)
end

function PANEL:ScrollToChild(panel)
	self:InvalidateLayout(true)

	local x, y = self.pnlCanvas:GetChildPosition(panel)
	local width, height = panel:GetSize()
	local viewWidth = self:GetWide() - (self.VBar.Enabled and self.VBar:GetWide() or 0)
	local viewHeight = self:GetTall() - (self.HBar.Enabled and self.HBar:GetTall() or 0)

	self.HBar:AnimateTo(x + width * 0.5 - viewWidth * 0.5, 0.5, 0, 0.5)
	self.VBar:AnimateTo(y + height * 0.5 - viewHeight * 0.5, 0.5, 0, 0.5)
end

